    const MPI_Info     info     = mpiwrapper_info_fromabi(abi_info);           \
                                                                               \
    MPI_Request request;                                                       \
    const int   ierror =                                                       \
        TARGET(sendbuf, recvbuf, count, datatype, op, comm, info, &request);   \
