#define BODY_MPI_File_open(TARGET)                                             \
  {                                                                            \
    (void)abi_comm;                                                            \
    (void)abi_filename;                                                        \
    (void)abi_amode;                                                           \
    (void)abi_info;                                                            \
    (void)abi_fh;                                                              \
    *abi_fh = MPIABI_FILE_NULL;                                                \
    return MPIABI_ERR_UNSUPPORTED_OPERATION;                                   \
  }
#endif

