#define BODY_MPI_Gather_init(TARGET)                                           \
  {                                                                            \
    (void)abi_sendbuf;                                                         \
    (void)abi_sendcount;                                                       \
    (void)abi_sendtype;                                                        \
    (void)abi_recvbuf;                                                         \
    (void)abi_recvcount;                                                       \
    (void)abi_recvtype;                                                        \
    (void)abi_root;                                                            \
    (void)abi_comm;                                                            \
    (void)abi_info;                                                            \
    (void)abi_request;                                                         \
    *abi_request = MPIABI_REQUEST_NULL;                                        \
    return MPIABI_ERR_UNSUPPORTED_OPERATION;                                   \
  }
#endif

