/* --------------------------------------------------------- MPI_Group_excl */

#ifdef MPIWRAPPER_HAVE_MPI_Group_excl
#define BODY_MPI_Group_excl(TARGET)                                            \
  {                                                                            \
    const MPI_Group group = mpiwrapper_group_fromabi(abi_group);               \
    const int       n     = abi_n;                                             \
    if (n < 0) return MPIABI_ERR_COUNT;                                        \
                                                                               \
    int  ranks_stack[MPIWRAPPER_STAGE_BYTES / sizeof(int)];                    \
    int *ranks      = NULL;                                                    \
    int  abi_ierror = MPIABI_ERR_INTERN;                                       \
                                                                               \
    ranks = mpiwrapper_stage(ranks_stack, sizeof ranks_stack, (size_t)n,       \
                             sizeof *ranks);                                   \
    if (!ranks) goto done;                                                     \
                                                                               \
    for (int i = 0; i < n; ++i)                                                \
      ranks[i] = mpiwrapper_rank_fromabi(abi_ranks[i]);                        \
                                                                               \
    {                                                                          \
      MPI_Group newgroup;                                                      \
      const int ierror = TARGET(group, n, ranks, &newgroup);                   \
                                                                               \
      *abi_newgroup = (ierror == MPI_SUCCESS)                                  \
                          ? mpiwrapper_group_toabi(newgroup)                   \
                          : MPIABI_GROUP_NULL;                                 \
      abi_ierror = mpiwrapper_errorcode_toabi(ierror);                         \
      if (mpiwrapper_take_handle_error()) abi_ierror = MPIABI_ERR_INTERN;      \
    }                                                                          \
                                                                               \
  done:                                                                        \
    mpiwrapper_unstage(ranks, ranks_stack);                                    \
    return abi_ierror;                                                         \
  }
#else
#define BODY_MPI_Group_excl(TARGET)                                            \
  {                                                                            \
    (void)abi_group;                                                           \
    (void)abi_n;                                                               \
    (void)abi_ranks;                                                           \
    (void)abi_newgroup;                                                        \
    *abi_newgroup = MPIABI_GROUP_NULL;                                         \
    return MPIABI_ERR_UNSUPPORTED_OPERATION;                                   \
  }
#endif

