#ifdef MPIWRAPPER_HAVE_MPI_Intercomm_create
#define BODY_MPI_Intercomm_create(TARGET)                                      \
  {                                                                            \
    const MPI_Comm local_comm    = mpiwrapper_comm_fromabi(abi_local_comm);    \
    const int      local_leader  = mpiwrapper_rank_fromabi(abi_local_leader);  \
    const MPI_Comm peer_comm     = mpiwrapper_comm_fromabi(abi_peer_comm);     \
    const int      remote_leader = mpiwrapper_rank_fromabi(abi_remote_leader); \
    const int      tag           = mpiwrapper_tag_fromabi(abi_tag);            \
                                                                               \
    MPI_Comm  newintercomm;                                                    \
    const int ierror =                                                         \
        TARGET(local_comm, local_leader, peer_comm, remote_leader, tag,        \
               &newintercomm);                                                 \
                                                                               \
    *abi_newintercomm = (ierror == MPI_SUCCESS)                                \
                            ? mpiwrapper_comm_toabi(newintercomm)              \
                            : MPIABI_COMM_NULL;                                \
    if (mpiwrapper_take_handle_error()) return MPIABI_ERR_INTERN;              \
    return mpiwrapper_errorcode_toabi(ierror);                                 \
  }
#else
#define BODY_MPI_Intercomm_create(TARGET)                                      \
  {                                                                            \
    (void)abi_local_comm;                                                      \
    (void)abi_local_leader;                                                    \
    (void)abi_peer_comm;                                                       \
    (void)abi_remote_leader;                                                   \
    (void)abi_tag;                                                             \
    (void)abi_newintercomm;                                                    \
    *abi_newintercomm = MPIABI_COMM_NULL;                                      \
    return MPIABI_ERR_UNSUPPORTED_OPERATION;                                   \
  }
#endif

