  {                                                                            \
    (void)abi_size;                                                            \
    (void)abi_rank;                                                            \
    (void)abi_ndims;                                                           \
    (void)abi_array_of_gsizes;                                                 \
    (void)abi_array_of_distribs;                                               \
    (void)abi_array_of_dargs;                                                  \
    (void)abi_array_of_psizes;                                                 \
    (void)abi_order;                                                           \
    (void)abi_oldtype;                                                         \
    (void)abi_newtype;                                                         \
    *abi_newtype = MPIABI_DATATYPE_NULL;                                       \
    return MPIABI_ERR_UNSUPPORTED_OPERATION;                                   \
  }
#endif

